<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Notification\Message\Domain\ValueObject\Holder\MessageUrgentAttributeHolder;
use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the MessageUrgentAttributeHolder trait.
 *
 * Covers assignment, retrieval, default fallback,
 * transfer between holders, validation rules, and unset operations.
 */
class MessageUrgentAttributeHolderUnitTest extends TestCase
{
    /**
     * Asserts that the code attribute is not assigned by default
     * and that isUrgent returns null on a freshly created holder.
     */
    public function testUrgentNotAssignedByDefault(): void
    {
        // Arrange
        $holder = new ImplWithMessageUrgentAttributeHolderUnitTest();

        // Assert
        $this->assertFalse($holder->isUrgentAssigned());
        $this->assertNull($holder->isUrgent());
    }
}
class ImplWithMessageUrgentAttributeHolderUnitTest
{
    use MessageUrgentAttributeHolder;
    public function assertRules(ConstraintFailList $errorsList): self
    {
        $result = new self();
        $this->withAssertedUrgentRules($result, $errorsList);
        return $result;
    }

    public function applyDefaults(): void
    {
        $this->withDefaultUrgent();
    }
}
